SOURCES=[
('D01','Broadcom KB 442835: Tier-0 VRF and parent HA mode','https://knowledge.broadcom.com/external/article/442835/cannot-add-tier0-vrf-gateway-to-a-tier0.html','Cause and Resolution; inspected full public page.','Gateway-mode compatibility check only; no site configuration or universal release certification.'),
('D02','OpenStack Neutron networking concepts','https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html','Concepts: Security groups, Ports, Provider networks; inspected public development documentation.','Additive policy, defaults and port-authority context; selected distribution/backend remains unqualified.'),
('D03','Nutanix Terraform provider official repository','https://github.com/nutanix/terraform-provider-nutanix','README: compatibility, resources and lifecycle/release notes; inspected public repository.','No provider version selected; package provenance and actual lifecycle support need a site decision.'),
('D04','HashiCorp: terraform_remote_state data source','https://developer.hashicorp.com/terraform/language/state/remote-state-data','Alternative ways to share data between configurations; inspected full public page.','State-read privilege and scoped publication context; no tool deployment prescribed.'),
('D05','RFC 7766: DNS Transport over TCP','https://datatracker.ietf.org/doc/html/rfc7766','Implementation requirements and TCP support; inspected official RFC text.','Protocol-completeness context; not a measured resolver or encrypted-DNS qualification.'),
('D06','RFC 7348: VXLAN packet format','https://www.rfc-editor.org/info/rfc7348/','Sections 4.3 and 5; inspected official RFC text and packet layout.','Informational packet-format basis; examples exclude extra tags, options and nested/encrypted encapsulation.'),
('D07','OpenStack Neutron OVN reference architecture','https://docs.openstack.org/neutron/latest/admin/ovn/refarch/refarch.html','Roles and distributed/external routing; inspected public development documentation.','Backend-specific conceptual behaviour; no distribution or supported production release selected.'),
('D08','OpenStack Nova host aggregates','https://docs.openstack.org/nova/latest/admin/aggregates.html','Tenant isolation and scheduler/Placement aggregate configuration; inspected public development documentation.','Placement-mechanism context; not proof of actual enforced co-residency.')]

def main():
    out=ROOT/'08_Development_Source'
    (out/'documents.json').write_text(json.dumps(D,ensure_ascii=False,indent=2))
    sources=[dict(id=i,title=t,url=u,locator=l,limitation=m,reviewed='2026-09-17',basis='Fresh external mechanism review') for i,t,u,l,m in SOURCES]
    (out/'sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2))
    print('Authored',len(D),'documents;',sum(len(v['sections']) for v in D.values()),'sections')
if __name__=='__main__':main()
